contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address receiver, uint amt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(receiver != address(c));
        require(receiver != address(this));
        require(address(this).balance >= amt);
        // Fund C: owner sends amt to this test, then back to C.
        c.sendTo(address(this), amt); if (__ESBMC_reverted()) return;
        c.sendTo(address(1600), 0); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;
        require(balBefore >= amt);
        uint recvBefore = receiver.balance;
        bool ok;
        c.sendTo(receiver, amt); bool __rev0 = __ESBMC_reverted(); if (__rev0) { ok = false; } else { ok = true; }
        assert(ok && address(c).balance == balBefore - amt && receiver.balance == recvBefore + amt);
    }
    receive() external payable {}
}

