// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MyContract c;

    function setUp() public {
        c = new MyContract();
    }

    function _run(address receiver, uint256 amt) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(receiver != address(c));
        vm.assume(receiver != address(this));
        vm.assume(address(this).balance >= amt);
        try c.sendTo(address(this), amt) {} catch { return; }
        try c.sendTo(address(1600), 0) {} catch { return; }
        uint balBefore = address(c).balance;
        vm.assume(balBefore >= amt);
        uint recvBefore = receiver.balance;
        bool ok;
        try c.sendTo(receiver, amt) { ok = true; } catch { ok = false; }
        assertTrue(ok && address(c).balance == balBefore - amt && receiver.balance == recvBefore + amt);
    }

    function testFuzz_run(address receiver, uint256 amt) public {
        vm.assume(receiver.code.length == 0 && uint160(receiver) > 0xffff && receiver != address(this) && receiver != address(c) && receiver != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && receiver != 0x000000000000000000636F6e736F6c652e6c6f67 && receiver != 0x4e59b44847b379578588920cA78FbF26c0B4956C && receiver != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(receiver, amt);
    }

    receive() external payable {}
}
